INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c7fba1d-b1eb-5fec-bb42-edeae2805b0e', 'Philippines Department Administrative Order', 'Department Administrative Order No. 2000-81', 'DAO No. 2000-81 implements the rules and regulations of the "Philippine Clean Air Act of 1999" where the following provisions are required: the National Air Quality Status Report, Self-Monitoring Reports, and Environmental Management System audit reports. The requirements provided are specifically targeted towards industries with significant emissions, heavy industries and extractive industries.', 'DAO No. 2000-81 implements the rules and regulations of the "Philippine Clean Air Act of 1999" where the following provisions are required: the National Air Quality Status Report, Self-Monitoring Reports, and Environmental Management System audit reports. The requirements provided are specifically targeted towards industries with significant emissions, heavy industries and extractive industries.', 'DAO No. 2000-81 implements the rules and regulations of the "Philippine Clean Air Act of 1999" where the following provisions are required: the National Air Quality Status Report, Self-Monitoring Reports, and Environmental Management System audit reports. The requirements provided are specifically targeted towards industries with significant emissions, heavy industries and extractive industries.', 'Philippines', 'climate', 'in_force', '2000-01-01'::date, 'Philippines', 'https://www.carrotsandsticks.org/policies/144_24', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'philippines']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('36010e91-9061-582b-8dc2-6e76ab4fb90f', 'Philippines Code of Proper Practices for Directors', 'Code of Proper Practices for Directors', 'This Code provides guidance so that directors can carry out their duties and responsibilities in accordance with the highest professional standards.', 'This Code provides guidance so that directors can carry out their duties and responsibilities in accordance with the highest professional standards.', 'This Code provides guidance so that directors can carry out their duties and responsibilities in accordance with the highest professional standards.', 'Philippines', 'governance', 'in_force', '2000-01-01'::date, 'Philippines', 'https://www.carrotsandsticks.org/policies/144_8', ARRAY['philippines', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8893da7f-8b91-5eac-a5ad-de8d71be44c7', 'Philippines Occupational Safety and Health in the Construction Industry', 'Guidelines Governing Occupational Safety and Health in the Construction Industry', 'In the interest of ensuring the protection and welfare of workers employed in the construction industry, the protection and welfare of the general public within and around the immediate vicinity of any construction worksite as well as the promotion of harmonious employer-employee relationships in the construction industry, and after consultations with the stakeholders in the construction industry, taking into consideration industry practices and applicable government requirements, the following guidelines are hereby issued for all concerned.', 'In the interest of ensuring the protection and welfare of workers employed in the construction industry, the protection and welfare of the general public within and around the immediate vicinity of any construction worksite as well as the promotion of harmonious employer-employee relationships in the construction industry, and after consultations with the stakeholders in the construction industry, taking into consideration industry practices and applicable government requirements, the following guidelines are hereby issued for all concerned.', 'In the interest of ensuring the protection and welfare of workers employed in the construction industry, the protection and welfare of the general public within and around the immediate vicinity of any construction worksite as well as the promotion of harmonious employer-employee relationships in the construction industry, and after consultations with the stakeholders in the construction industry, taking into consideration industry practices and applicable government requirements, the following guidelines are hereby issued for all concerned.', 'Philippines', 'social', 'in_force', '1998-01-01'::date, 'Philippines', 'https://www.carrotsandsticks.org/policies/144_15', ARRAY['guidance_frameworks', 'sdg8', 'other sustainability policy', 'sdg3', 'philippines', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a2bbb69-03e5-5ea8-b9b8-122ef35007a9', 'Philippines Department Order . Guidelines Governing Occupational Safety', 'Department Order No. 13. Guidelines Governing Occupational Safety and Health in the Construction Industry', 'DO No. 13 provides guidelines governing occupational safety and health in the construction industry. Under the coverage of the order are the following: construction safety and health program; personal protective equipment; safety personnel; emergency occupational health personnel and facilities; construction safety signage; safety on construction heavy equipment; construction safety and health committee; safety and health information; construction safety and health training; construction safety and health reports; construction workers skills certificates; workers'' welfare facilities; and construction safety and health program. Not only does the department order require the submission of a safety and health report, but it also provides the guidelines for a safe and secure for the workers and the people that may be potentially exposed to the dangers of construction.', 'DO No. 13 provides guidelines governing occupational safety and health in the construction industry. Under the coverage of the order are the following: construction safety and health program; personal protective equipment; safety personnel; emergency occupational health personnel and facilities; construction safety signage; safety on construction heavy equipment; construction safety and health committee; safety and health information; construction safety and health training; construction safety and health reports; construction workers skills certificates; workers'' welfare facilities; and construction safety and health program. Not only does the department order require the submission of a safety and health report, but it also provides the guidelines for a safe and secure for the workers and the people that may be potentially exposed to the dangers of construction.', 'DO No. 13 provides guidelines governing occupational safety and health in the construction industry. Under the coverage of the order are the following: construction safety and health program; personal protective equipment; safety personnel; emergency occupational health personnel and facilities; construction safety signage; safety on construction heavy equipment; construction safety and health committee; safety and health information; construction safety and health training; construction safety and health reports; construction workers skills certificates; workers'' welfare facilities; and construction safety and health program. Not only does the department order require the submission of a safety and health report, but it also provides the guidelines for a safe and secure for the workers and the people that may be potentially exposed to the dangers of construction.', 'Philippines', 'climate', 'in_force', '1998-01-01'::date, 'Philippines', 'https://www.carrotsandsticks.org/policies/144_25', ARRAY['sdg4', 'guidance_frameworks', 'sdg8', 'other sustainability policy', 'sdg3', 'philippines', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9e1628a0-c46f-55db-b6e2-7ba84d6520de', 'Philippines act instituting a new system of mineral resources', 'An act instituting a new system of mineral resources exploration, development, utilization and conservation', 'This document outlines the Philippine Mining Act of 1995, an act instituting a new system of mineral resources exploration, development, utilization and conservation.', 'This document outlines the Philippine Mining Act of 1995, an act instituting a new system of mineral resources exploration, development, utilization and conservation.', 'This document outlines the Philippine Mining Act of 1995, an act instituting a new system of mineral resources exploration, development, utilization and conservation.', 'Philippines', 'climate', 'in_force', '1995-01-01'::date, 'Philippines', 'https://www.carrotsandsticks.org/policies/144_14', ARRAY['philippines', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c07fa66e-91b6-5dc7-a7ea-d2f6d43dc019', 'Poland Act of 4 June 2025 amending the Act', 'Act of 4 June 2025 amending the Act - Labor Code', 'The Act amends the Polish Labor Code to require employers to provide salary information and collective bargaining details to job applicants, promoting fair and transparent recruitment practices. It aims to prevent gender discrimination in job announcements and recruitment processes, taking effect 6 months after publication, targeting employers and job seekers in Poland.', 'The Act amends the Polish Labor Code to require employers to provide salary information and collective bargaining details to job applicants, promoting fair and transparent recruitment practices. It aims to prevent gender discrimination in job announcements and recruitment processes, taking effect 6 months after publication, targeting employers and job seekers in Poland.', 'The Act amends the Polish Labor Code to require employers to provide salary information and collective bargaining details to job applicants, promoting fair and transparent recruitment practices. It aims to prevent gender discrimination in job announcements and recruitment processes, taking effect 6 months after publication, targeting employers and job seekers in Poland.', 'Poland', 'nature', 'in_force', '2025-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_19', ARRAY['sdg10', 'regulations', 'mandatory', 'sdg5', 'sdg15', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e637fca1-1614-5789-8024-696ca6fd5556', 'Poland Act of 9 July 2025 amending the Act', 'Act of 9 July 2025 amending the Act amending the Accounting Act, the Act on statutory auditors, audit firms and public oversight and certain other acts', 'The Act of 9 July 2025 amends previous legislation related to accounting and auditing in Poland, specifically extending deadlines for compliance with sustainability reporting requirements. It applies to all companies subject to the Accounting Act and aligns with European Union directives on corporate sustainability reporting. The key requirement involves adhering to new deadlines for reporting, which have been postponed to 2026 and 2027. This legislation is mandatory for affected entities and aims to enhance transparency in sustainability practices.', 'The Act of 9 July 2025 amends previous legislation related to accounting and auditing in Poland, specifically extending deadlines for compliance with sustainability reporting requirements. It applies to all companies subject to the Accounting Act and aligns with European Union directives on corporate sustainability reporting. The key requirement involves adhering to new deadlines for reporting, which have been postponed to 2026 and 2027. This legislation is mandatory for affected entities and aims to enhance transparency in sustainability practices.', 'The Act of 9 July 2025 amends previous legislation related to accounting and auditing in Poland, specifically extending deadlines for compliance with sustainability reporting requirements. It applies to all companies subject to the Accounting Act and aligns with European Union directives on corporate sustainability reporting. The key requirement involves adhering to new deadlines for reporting, which have been postponed to 2026 and 2027. This legislation is mandatory for affected entities and aims to enhance transparency in sustainability practices.', 'Poland', 'climate', 'in_force', '2025-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_21', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ec64718e-9183-501b-a0ea-393327fb4ef0', 'Poland item 1863 Act of December 6, 2024, amending', 'item 1863 Act of December 6, 2024, amending the Act on Audit, the Act on Statutory Auditors, Audit Firms, and Public Oversight, and other acts', 'This policy was published in 2024 by Poland. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2024 by Poland. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2024 by Poland. It addresses sustainability and corporate responsibility requirements.', 'Poland', 'nature', 'in_force', '2024-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_20', ARRAY['sdg15', 'mandatory', 'poland', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5c9aa6c2-2da8-5965-8099-34a6d98c3102', 'Poland ESG Reporting Guidelines – Guide for Issuers', 'ESG Reporting Guidelines – Guide for Issuers', 'The ESG Reporting Guidelines were published in May 2021 by the Warsaw Stock Exchange (WSE) in collaboration with the European Bank for Reconstruction and Development (EBRD) and Steward Redqueen. These guidelines serve as a practical framework for companies listed on the WSE to enhance their sustainability reporting practices, aligning with Polish and EU regulations.

Key provisions include:

Definition of ESG Reporting: Explains why Environmental, Social, and Governance (ESG) factors are critical for businesses.
Regulatory Context: Aligns with the EU Non-Financial Reporting Directive (NFRD), Sustainable Finance Disclosure Regulation (SFDR), and EU Taxonomy Regulation.
Reporting Principles: Encourages transparent, standardized, and decision-useful sustainability disclosures.
Materiality Assessment: Recommends companies determine key ESG risks and opportunities.
Reporting Formats: Provides guidance on structuring reports, including integrated reporting, stand-alone sustainability reports, and annual financial statements.
Key ESG Indicators: Suggests sector-specific and general sustainability metrics, including those aligned with Global Reporting Initiative (GRI), Sustainability Accounting Standards Board (SASB), and Task Force on Climate-related Financial Disclosures (TCFD).
Investor-Oriented Reporting: Addresses growing demand from investors, regulators, and stakeholders for consistent and comparable ESG data.
The guidelines aim to enhance corporate transparency, investor confidence, and sustainable development in Poland while aligning with international ESG best practices.', 'The ESG Reporting Guidelines were published in May 2021 by the Warsaw Stock Exchange (WSE) in collaboration with the European Bank for Reconstruction and Development (EBRD) and Steward Redqueen. These guidelines serve as a practical framework for companies listed on the WSE to enhance their sustainability reporting practices, aligning with Polish and EU regulations.

Key provisions include:

Definition of ESG Reporting: Explains why Environmental, Social, and Governance (ESG) factors are critical for businesses.
Regulatory Context: Aligns with the EU Non-Financial Reporting Directive (NFRD), Sustainable Finance Disclosure Regulation (SFDR), and EU Taxonomy Regulation.
Reporting Principles: Encourages transparent, standardized, and decision-useful sustainability disclosures.
Materiality Assessment: Recommends companies determine key ESG risks and opportunities.
Reporting Formats: Provides guidance on structuring reports, including integrated reporting, stand-alone sustainability reports, and annual financial statements.
Key ESG Indicators: Suggests sector-specific and general sustainability metrics, including those aligned with Global Reporting Initiative (GRI), Sustainability Accounting Standards Board (SASB), and Task Force on Climate-related Financial Disclosures (TCFD).
Investor-Oriented Reporting: Addresses growing demand from investors, regulators, and stakeholders for consistent and comparable ESG data.
The guidelines aim to enhance corporate transparency, investor confidence, and sustainable development in Poland while aligning with international ESG best practices.', 'The ESG Reporting Guidelines were published in May 2021 by the Warsaw Stock Exchange (WSE) in collaboration with the European Bank for Reconstruction and Development (EBRD) and Steward Redqueen. These guidelines serve as a practical framework for companies listed on the WSE to enhance their sustainability reporting practices, aligning with Polish and EU regulations.

Key provisions include:

Definition of ESG Reporting: Explains why Environmental, Social, and Governance (ESG) factors are critical for businesses.
Regulatory Context: Aligns with the EU Non-Financial Reporting Directive (NFRD), Sustainable Finance Disclosure Regulation (SFDR), and EU Taxonomy Regulation.
Reporting Principles: Encourages transparent, standardized, and decision-useful sustainability disclosures.
Materiality Assessment: Recommends companies determine key ESG risks and opportunities.
