INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d135b681-55c2-5474-ad6d-711edc4e779e', 'Poland Act of July 17, 2009, of on the', 'Act of July 17, 2009, of on the Management of Greenhouse Emissions and Other Substances (Dz.U. 2009, No. 130, Item 1070)', 'This Act sets up principles to limit greenhouse gas emissions and other substances in order to comply with Poland''s obligations towards the EU and the UNFCCC. It introduces three mechanisms under the Kyoto Protocol: emissions trading, the clean development mechanism and joint implementation.', 'This Act sets up principles to limit greenhouse gas emissions and other substances in order to comply with Poland''s obligations towards the EU and the UNFCCC. It introduces three mechanisms under the Kyoto Protocol: emissions trading, the clean development mechanism and joint implementation.', 'This Act sets up principles to limit greenhouse gas emissions and other substances in order to comply with Poland''s obligations towards the EU and the UNFCCC. It introduces three mechanisms under the Kyoto Protocol: emissions trading, the clean development mechanism and joint implementation.', 'Poland', 'climate', 'in_force', '2009-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_14', ARRAY['sdg13', 'regulations', 'mandatory', 'disclosure', 'sdg15', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1eab1ae9-dc37-5553-b6b9-1e48e6c9dd63', 'Poland providing information on the environment and environmental protection', 'Act on providing information on the environment and environmental protection, public participation in environmental protection and on environmental impact assessment', 'This Act lays down: (1) rules of proceedings in the cases concerning making information on environment and its protection available, assessment of impact on the environment and transboundary impact on the environment; (2) rules of public participation in environmental protection; (3) administration organs competent at matters specified in point 1. Everybody has the right to access to information on the environment and its protection on conditions laid down in this Act. Everybody has also the right to participate in proceedings requiring public participation. The present Act is composed of the following sections: General provisions (sec. 1); Making information on environment and its protection available (sec. 2); Public participation in environmental protection (sec. 3); Strategic assessment of environmental impact (sec. 4); Assessment of the impact of undertakings on the environment and the area Nature 2000 (sec. 5); Transboundary impact on the environment (sec. 6); General Director of Environmental Protection and regional directors of environmental protection (sec. 7); Changes in valid provisions, transitional and final provisions (sec. 8).', 'This Act lays down: (1) rules of proceedings in the cases concerning making information on environment and its protection available, assessment of impact on the environment and transboundary impact on the environment; (2) rules of public participation in environmental protection; (3) administration organs competent at matters specified in point 1. Everybody has the right to access to information on the environment and its protection on conditions laid down in this Act. Everybody has also the right to participate in proceedings requiring public participation. The present Act is composed of the following sections: General provisions (sec. 1); Making information on environment and its protection available (sec. 2); Public participation in environmental protection (sec. 3); Strategic assessment of environmental impact (sec. 4); Assessment of the impact of undertakings on the environment and the area Nature 2000 (sec. 5); Transboundary impact on the environment (sec. 6); General Director of Environmental Protection and regional directors of environmental protection (sec. 7); Changes in valid provisions, transitional and final provisions (sec. 8).', 'This Act lays down: (1) rules of proceedings in the cases concerning making information on environment and its protection available, assessment of impact on the environment and transboundary impact on the environment; (2) rules of public participation in environmental protection; (3) administration organs competent at matters specified in point 1. Everybody has the right to access to information on the environment and its protection on conditions laid down in this Act. Everybody has also the right to participate in proceedings requiring public participation. The present Act is composed of the following sections: General provisions (sec. 1); Making information on environment and its protection available (sec. 2); Public participation in environmental protection (sec. 3); Strategic assessment of environmental impact (sec. 4); Assessment of the impact of undertakings on the environment and the area Nature 2000 (sec. 5); Transboundary impact on the environment (sec. 6); General Director of Environmental Protection and regional directors of environmental protection (sec. 7); Changes in valid provisions, transitional and final provisions (sec. 8).', 'Poland', 'nature', 'in_force', '2008-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_18', ARRAY['regulations', 'mandatory', 'disclosure', 'sdg15', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9650532-db4b-58e2-81b2-9b83f552aa07', 'Poland Code of Best Practice for WSE Listed Companies', 'Code of Best Practice for WSE Listed Companies, 2007', '“The Code of Best Practice for WSE Listed Companies” aims at enhancing transparency of listed companies, improving quality of communication between companies and investors, and strengthening protection of shareholders’ rights, including those not regulated by legislation, while refraining from imposing a burden on listed companies that may outweigh the benefits resulting from market needs. The Code of Best Practice therefore only addresses those areas where its application may have a positive impact on the market valuation of companies, thus reducing the cost of capital.', '“The Code of Best Practice for WSE Listed Companies” aims at enhancing transparency of listed companies, improving quality of communication between companies and investors, and strengthening protection of shareholders’ rights, including those not regulated by legislation, while refraining from imposing a burden on listed companies that may outweigh the benefits resulting from market needs. The Code of Best Practice therefore only addresses those areas where its application may have a positive impact on the market valuation of companies, thus reducing the cost of capital.', '“The Code of Best Practice for WSE Listed Companies” aims at enhancing transparency of listed companies, improving quality of communication between companies and investors, and strengthening protection of shareholders’ rights, including those not regulated by legislation, while refraining from imposing a burden on listed companies that may outweigh the benefits resulting from market needs. The Code of Best Practice therefore only addresses those areas where its application may have a positive impact on the market valuation of companies, thus reducing the cost of capital.', 'Poland', 'governance', 'in_force', '2007-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_7', ARRAY['regulations', 'sdg16', 'disclosure', 'voluntary', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a50de487-bf1b-59bd-a558-2a665dff2b61', 'Poland Best Practices in Public Companies', 'Best Practices in Public Companies 2005', 'This compilation of best practices, worked out for the needs of the Polish capital market, sets out the fundamentals of corporate governance standards in a public joint-stock company. It is not an exhaustive list. Drawn up on the basis of Polish experience, it should be constantly developed in line with changing market needs.', 'This compilation of best practices, worked out for the needs of the Polish capital market, sets out the fundamentals of corporate governance standards in a public joint-stock company. It is not an exhaustive list. Drawn up on the basis of Polish experience, it should be constantly developed in line with changing market needs.', 'This compilation of best practices, worked out for the needs of the Polish capital market, sets out the fundamentals of corporate governance standards in a public joint-stock company. It is not an exhaustive list. Drawn up on the basis of Polish experience, it should be constantly developed in line with changing market needs.', 'Poland', 'governance', 'in_force', '2005-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_2', ARRAY['regulations', 'sdg16', 'disclosure', 'voluntary', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7f23a344-a0f7-52e6-a4c3-ef5623fec8ae', 'Poland Environmental Protection Act', 'Environmental Protection Act', 'This Act lays down the general principles of environment protection in Poland, creates a framework for administration, planning and decision-making at the national level, and regulates various matters related to environment protection, in particular the principles of the establishment of: (a) the conditions for the protection of environmental resources; (b) the conditions for the release of substances or energies into the environment; (c) the costs of the use of the environment. The present Act is composed of the following sections: General provisions (sec. 1); Protection of environmental resources, i.e. air, water, land, noise pollution, electro-magnetic pollution, animals and plants (sec. 2); Pollution prevention (sec. 3); Serious breakdowns (sec. 4); Financial and legal assets (sec. 5); Liability in environment protection (sec. 6); Authorities and institutions of environment protection (sec. 7); Final provision (sec. 9). This Act establishes also an ecological policy for creating conditions required to introduce environment protection.', 'This Act lays down the general principles of environment protection in Poland, creates a framework for administration, planning and decision-making at the national level, and regulates various matters related to environment protection, in particular the principles of the establishment of: (a) the conditions for the protection of environmental resources; (b) the conditions for the release of substances or energies into the environment; (c) the costs of the use of the environment. The present Act is composed of the following sections: General provisions (sec. 1); Protection of environmental resources, i.e. air, water, land, noise pollution, electro-magnetic pollution, animals and plants (sec. 2); Pollution prevention (sec. 3); Serious breakdowns (sec. 4); Financial and legal assets (sec. 5); Liability in environment protection (sec. 6); Authorities and institutions of environment protection (sec. 7); Final provision (sec. 9). This Act establishes also an ecological policy for creating conditions required to introduce environment protection.', 'This Act lays down the general principles of environment protection in Poland, creates a framework for administration, planning and decision-making at the national level, and regulates various matters related to environment protection, in particular the principles of the establishment of: (a) the conditions for the protection of environmental resources; (b) the conditions for the release of substances or energies into the environment; (c) the costs of the use of the environment. The present Act is composed of the following sections: General provisions (sec. 1); Protection of environmental resources, i.e. air, water, land, noise pollution, electro-magnetic pollution, animals and plants (sec. 2); Pollution prevention (sec. 3); Serious breakdowns (sec. 4); Financial and legal assets (sec. 5); Liability in environment protection (sec. 6); Authorities and institutions of environment protection (sec. 7); Final provision (sec. 9). This Act establishes also an ecological policy for creating conditions required to introduce environment protection.', 'Poland', 'nature', 'in_force', '2001-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_13', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'sdg15', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2d20598c-d483-58a8-a531-8b10a14be346', 'Poland Commercial Companies Code', 'The Commercial Companies Code', 'This Code aims to regulate the creation, functioning, dissolution, merger, division and transformation of commercial companies. Under this Code commercial companies shall disclose a financial report with total entries in the tax book of receipts, expenses and other records kept for tax purposes.', 'This Code aims to regulate the creation, functioning, dissolution, merger, division and transformation of commercial companies. Under this Code commercial companies shall disclose a financial report with total entries in the tax book of receipts, expenses and other records kept for tax purposes.', 'This Code aims to regulate the creation, functioning, dissolution, merger, division and transformation of commercial companies. Under this Code commercial companies shall disclose a financial report with total entries in the tax book of receipts, expenses and other records kept for tax purposes.', 'Poland', 'climate', 'in_force', '2000-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_16', ARRAY['mandatory', 'poland', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed768784-6886-5c49-a50a-79bb7b186518', 'Poland Commercial Companies Code', 'The Commercial Companies Code', 'The Commercial Companies Code (KSH) currently in force in Poland was introduced by the Act of September 15, 2000 (Journal of Laws 2000 No. 94 item 1037, as amended). It is a basic legal act regulating the subject of commercial companies. It norms the processes of their establishment, operation, transformation and resolution. In other words, it shows how some entities set up to run a business can be traded.', 'The Commercial Companies Code (KSH) currently in force in Poland was introduced by the Act of September 15, 2000 (Journal of Laws 2000 No. 94 item 1037, as amended). It is a basic legal act regulating the subject of commercial companies. It norms the processes of their establishment, operation, transformation and resolution. In other words, it shows how some entities set up to run a business can be traded.', 'The Commercial Companies Code (KSH) currently in force in Poland was introduced by the Act of September 15, 2000 (Journal of Laws 2000 No. 94 item 1037, as amended). It is a basic legal act regulating the subject of commercial companies. It norms the processes of their establishment, operation, transformation and resolution. In other words, it shows how some entities set up to run a business can be traded.', 'Poland', 'nature', 'in_force', '2000-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_6', ARRAY['regulations', 'mandatory', 'disclosure', 'sdg15', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c3e6ca12-9a75-51e6-9846-4c7a6cbdcf95', 'Poland Labour Code', 'The Labour Code', 'The Labour Code is the key legal act regulating relations between employers and employees. It sets out conditions under which work can be carried out in Poland.', 'The Labour Code is the key legal act regulating relations between employers and employees. It sets out conditions under which work can be carried out in Poland.', 'The Labour Code is the key legal act regulating relations between employers and employees. It sets out conditions under which work can be carried out in Poland.', 'Poland', 'nature', 'in_force', '1997-01-01'::date, 'Poland', 'https://www.carrotsandsticks.org/policies/145_5', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg15', 'poland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('da6b554d-120d-55c0-8b2d-ede662c19ee6', 'Portugal Sustainability guide', 'Sustainability guide', 'The Sustainability Guide 2024 from Portugal aims to support supervised entities in complying with sustainable finance regulations. It organizes rules by market sector, provides guidance, and encourages best practices aligned with CMVM and ESMA standards to enhance market credibility and investor trust. Target audience: supervised entities in the capital markets.', 'The Sustainability Guide 2024 from Portugal aims to support supervised entities in complying with sustainable finance regulations. It organizes rules by market sector, provides guidance, and encourages best practices aligned with CMVM and ESMA standards to enhance market credibility and investor trust. Target audience: supervised entities in the capital markets.', 'The Sustainability Guide 2024 from Portugal aims to support supervised entities in complying with sustainable finance regulations. It organizes rules by market sector, provides guidance, and encourages best practices aligned with CMVM and ESMA standards to enhance market credibility and investor trust. Target audience: supervised entities in the capital markets.', 'Portugal', 'climate', 'in_force', '2025-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_52', ARRAY['sdg13', 'portugal', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5674c4fe-9e96-58cf-98ac-17dc7feafc3a', 'Portugal Law Global Minimum Tax Regime', 'Law No. 41/2024 Global Minimum Tax Regime', 'Law No. 41/2024 in Portugal implements the EU Directive 2022/2523, establishing a global minimum tax for multinational and large national companies. It includes provisions for transitional arrangements and safeguards based on financial and tax reporting by country or jurisdiction, targeting multinational groups and national entities.', 'Law No. 41/2024 in Portugal implements the EU Directive 2022/2523, establishing a global minimum tax for multinational and large national companies. It includes provisions for transitional arrangements and safeguards based on financial and tax reporting by country or jurisdiction, targeting multinational groups and national entities.', 'Law No. 41/2024 in Portugal implements the EU Directive 2022/2523, establishing a global minimum tax for multinational and large national companies. It includes provisions for transitional arrangements and safeguards based on financial and tax reporting by country or jurisdiction, targeting multinational groups and national entities.', 'Portugal', 'climate', 'in_force', '2024-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_53', ARRAY['mandatory', 'portugal', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf53e26c-aeeb-5f68-b749-f7b8eedc6bcc', 'Portugal Decree-Law', 'Decree-Law 24/2024', 'Decree-Law 24/2024 in Portugal amends waste management regulations to align with EU directives, promote innovation in waste treatment, and enhance environmental protection. It revises general waste management, landfill deposition, and specific waste flow regulations, emphasizing waste reduction, recycling, and producer responsibility. Targeted at waste producers, treatment operators, and municipalities.', 'Decree-Law 24/2024 in Portugal amends waste management regulations to align with EU directives, promote innovation in waste treatment, and enhance environmental protection. It revises general waste management, landfill deposition, and specific waste flow regulations, emphasizing waste reduction, recycling, and producer responsibility. Targeted at waste producers, treatment operators, and municipalities.', 'Decree-Law 24/2024 in Portugal amends waste management regulations to align with EU directives, promote innovation in waste treatment, and enhance environmental protection. It revises general waste management, landfill deposition, and specific waste flow regulations, emphasizing waste reduction, recycling, and producer responsibility. Targeted at waste producers, treatment operators, and municipalities.', 'Portugal', 'climate', 'in_force', '2024-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_55', ARRAY['portugal', 'regulations', 'sdg9', 'sdg11', 'mandatory', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('674a0d23-d724-5c1b-b639-5b502d5331dc', 'Portugal Decree-Law', 'Decree-Law 22/2024', 'Decree-Law 22/2024 in Portugal extends simplified procedures for renewable energy production, aligning with national and EU energy goals. The amendment aims to accelerate a fair energy transition, emphasizing ecological responsibility and public interest.', 'Decree-Law 22/2024 in Portugal extends simplified procedures for renewable energy production, aligning with national and EU energy goals. The amendment aims to accelerate a fair energy transition, emphasizing ecological responsibility and public interest.', 'Decree-Law 22/2024 in Portugal extends simplified procedures for renewable energy production, aligning with national and EU energy goals. The amendment aims to accelerate a fair energy transition, emphasizing ecological responsibility and public interest.', 'Portugal', 'climate', 'in_force', '2024-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_56', ARRAY['portugal', 'regulations', 'sdg7', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a6b6f2bb-0e4e-574b-b4e4-007e89ef8d59', 'Portugal Decree-Law', 'Decree-Law 4/2024', 'Decree-Law 4/2024 establishes a voluntary carbon market in Portugal to achieve carbon neutrality. It outlines rules for reducing greenhouse gas emissions, promoting carbon sequestration, and fostering biodiversity protection. The policy targets both public and private entities to engage in emission reduction projects and carbon offsetting initiatives.', 'Decree-Law 4/2024 establishes a voluntary carbon market in Portugal to achieve carbon neutrality. It outlines rules for reducing greenhouse gas emissions, promoting carbon sequestration, and fostering biodiversity protection. The policy targets both public and private entities to engage in emission reduction projects and carbon offsetting initiatives.', 'Decree-Law 4/2024 establishes a voluntary carbon market in Portugal to achieve carbon neutrality. It outlines rules for reducing greenhouse gas emissions, promoting carbon sequestration, and fostering biodiversity protection. The policy targets both public and private entities to engage in emission reduction projects and carbon offsetting initiatives.', 'Portugal', 'climate', 'in_force', '2024-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_57', ARRAY['sdg13', 'portugal', 'regulations', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7306b66c-e92e-5742-b50f-b5bc260723d7', 'Portugal Portuguese Corporate Governance Code (IPCG Code – 2018', 'Portuguese Corporate Governance Code (IPCG Code – 2018, revised 2023)', 'The Portuguese Corporate Governance Code was first issued in 2018 by the Instituto Português de Corporate Governance (IPCG) and revised in 2020 and 2023. The Code establishes corporate governance best practices for publicly listed companies in Portugal, focusing on transparency, shareholder rights, sustainability, and board accountability.

Key provisions include:

Voluntary Compliance under the "Comply or Explain" Principle:
Companies are expected to follow the recommendations or provide justifications for non-compliance.
Corporate Responsibility & Sustainability (New Chapter I, 2023 Revision):
Aligns governance with the United Nations Sustainable Development Goals (SDGs).
Companies must identify and mitigate environmental and social risks.
Board Structure and Independence:
Guidelines for board diversity, executive/non-executive roles, and conflict of interest policies.
Internal Control & Risk Management (Chapter VII):
Requires companies to implement effective risk management frameworks, including climate risk assessments.
Encourages oversight of artificial intelligence (AI) in decision-making.
Transparency & Reporting Obligations:
Mandates clear financial and sustainability reporting (Chapter VIII).
Independent audits and disclosures on related-party transactions.
The 2023 revision enhances sustainability commitments, risk management, and reporting quality.', 'The Portuguese Corporate Governance Code was first issued in 2018 by the Instituto Português de Corporate Governance (IPCG) and revised in 2020 and 2023. The Code establishes corporate governance best practices for publicly listed companies in Portugal, focusing on transparency, shareholder rights, sustainability, and board accountability.

Key provisions include:

