INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8e19db03-2cd9-55af-85c0-d8ca26a79d49', 'Portugal Decree-Law', 'Decree-Law No. 11/2023', 'Decree-Law No. 11/2023 in Portugal aims to reform and simplify environmental licensing, reducing unnecessary administrative burdens to enhance business competitiveness. It focuses on streamlining processes, promoting environmental protection, and fostering economic growth while addressing challenges identified by international institutions. Targeted at businesses, citizens, and government entities.', 'Decree-Law No. 11/2023 in Portugal aims to reform and simplify environmental licensing, reducing unnecessary administrative burdens to enhance business competitiveness. It focuses on streamlining processes, promoting environmental protection, and fostering economic growth while addressing challenges identified by international institutions. Targeted at businesses, citizens, and government entities.', 'Decree-Law No. 11/2023 in Portugal aims to reform and simplify environmental licensing, reducing unnecessary administrative burdens to enhance business competitiveness. It focuses on streamlining processes, promoting environmental protection, and fostering economic growth while addressing challenges identified by international institutions. Targeted at businesses, citizens, and government entities.', 'Portugal', 'climate', 'in_force', '2023-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_54', ARRAY['mandatory', 'portugal', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('23d65f4c-b877-5323-909f-94432d04de74', 'Portugal Decree Law', 'Decree Law 27/2023', 'Decree Law 27/2023 in Portugal approves the asset management regime, unifying regulations for collective and individual asset management. It aligns national law with EU directives, aiming to promote sector competitiveness and harmonization. The target audience includes financial intermediaries and investors involved in collective capital investments.', 'Decree Law 27/2023 in Portugal approves the asset management regime, unifying regulations for collective and individual asset management. It aligns national law with EU directives, aiming to promote sector competitiveness and harmonization. The target audience includes financial intermediaries and investors involved in collective capital investments.', 'Decree Law 27/2023 in Portugal approves the asset management regime, unifying regulations for collective and individual asset management. It aligns national law with EU directives, aiming to promote sector competitiveness and harmonization. The target audience includes financial intermediaries and investors involved in collective capital investments.', 'Portugal', 'climate', 'in_force', '2023-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_58', ARRAY['mandatory', 'portugal', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e2604a0f-06d1-523e-be6d-c79e606ea54d', 'Banco de Portugal – ESG Risk Supervision &', 'Banco de Portugal – ESG Risk Supervision & Action Plan', 'This document outlines the Banco de Portugal’s ESG (Environmental, Social, and Governance) sustainability strategy for 2022-2025. It integrates ESG into the Bank’s financial stability, monetary policy, and internal management. The strategy aligns with the EU Green Deal, Network for Greening the Financial System (NGFS), and international ESG frameworks.

Key provisions include:

Climate and Financial Stability:
Assessing the impact of climate risks on monetary policy and financial stability.
Conducting climate stress tests on the Portuguese banking system.
Ensuring ESG-aligned investment portfolios.
Internal Sustainability Measures:
Reducing the Banco de Portugal’s ecological footprint.
Implementing green energy policies and sustainable asset management.
Corporate Governance & Social Responsibility:
Strengthening financial literacy, social inclusion, and diversity policies.
Improving risk management, transparency, and anti-corruption measures.
ESG Reporting & Disclosure:
Enhancing ESG disclosures in annual reports.
Aligning with EU climate disclosure standards.
Increasing stakeholder engagement on sustainability.
The plan ensures the integration of climate and sustainability concerns into Portugal’s financial system, improving economic resilience and regulatory alignment with EU climate goals.', 'This document outlines the Banco de Portugal’s ESG (Environmental, Social, and Governance) sustainability strategy for 2022-2025. It integrates ESG into the Bank’s financial stability, monetary policy, and internal management. The strategy aligns with the EU Green Deal, Network for Greening the Financial System (NGFS), and international ESG frameworks.

Key provisions include:

Climate and Financial Stability:
Assessing the impact of climate risks on monetary policy and financial stability.
Conducting climate stress tests on the Portuguese banking system.
Ensuring ESG-aligned investment portfolios.
Internal Sustainability Measures:
Reducing the Banco de Portugal’s ecological footprint.
Implementing green energy policies and sustainable asset management.
Corporate Governance & Social Responsibility:
Strengthening financial literacy, social inclusion, and diversity policies.
Improving risk management, transparency, and anti-corruption measures.
ESG Reporting & Disclosure:
Enhancing ESG disclosures in annual reports.
Aligning with EU climate disclosure standards.
Increasing stakeholder engagement on sustainability.
The plan ensures the integration of climate and sustainability concerns into Portugal’s financial system, improving economic resilience and regulatory alignment with EU climate goals.', 'This document outlines the Banco de Portugal’s ESG (Environmental, Social, and Governance) sustainability strategy for 2022-2025. It integrates ESG into the Bank’s financial stability, monetary policy, and internal management. The strategy aligns with the EU Green Deal, Network for Greening the Financial System (NGFS), and international ESG frameworks.

Key provisions include:

Climate and Financial Stability:
Assessing the impact of climate risks on monetary policy and financial stability.
Conducting climate stress tests on the Portuguese banking system.
Ensuring ESG-aligned investment portfolios.
Internal Sustainability Measures:
Reducing the Banco de Portugal’s ecological footprint.
Implementing green energy policies and sustainable asset management.
Corporate Governance & Social Responsibility:
Strengthening financial literacy, social inclusion, and diversity policies.
Improving risk management, transparency, and anti-corruption measures.
ESG Reporting & Disclosure:
Enhancing ESG disclosures in annual reports.
Aligning with EU climate disclosure standards.
Increasing stakeholder engagement on sustainability.
The plan ensures the integration of climate and sustainability concerns into Portugal’s financial system, improving economic resilience and regulatory alignment with EU climate goals.', 'Portugal', 'climate', 'in_force', '2022-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_6', ARRAY['sdg4', 'sdg13', 'sdg10', 'portugal', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('06b122cd-fe15-5204-8e40-57d1772c403d', 'Lei de Bases do Clima (Law , Portugal’s', 'Lei de Bases do Clima (Law No. 98/2021, Portugal’s Climate Framework Law)', 'Enacted in December 2021, Portugal’s Climate Framework Law establishes a comprehensive legal framework for climate policy, aligning with the Paris Agreement and the European Green Deal. The law formalizes Portugal’s commitment to carbon neutrality by 2050 and sets legally binding targets for greenhouse gas (GHG) reduction, renewable energy expansion, and climate adaptation measures.

Key provisions include:

Recognition of Climate Emergency: Acknowledges climate change as a national priority.
Emissions Reduction Targets:
55% reduction in GHG emissions by 2030 (compared to 2005 levels).
65-75% reduction by 2040.
Carbon neutrality by 2050.
Sectoral Climate Strategies: Requires national and regional authorities to integrate climate objectives into energy, transport, agriculture, and industrial policies.
Green Finance & Sustainable Investments:
Promotes sustainable finance, carbon pricing, and investment in renewable energy.
Phases out fossil fuel subsidies by 2030.
Corporate Climate Responsibility:
Companies must assess and disclose climate risks in investment decisions.
Publicly traded companies must report environmental and climate-related impacts.
Citizen Participation & Transparency:
Establishes a Climate Action Council (CAC) to monitor compliance and advise policymakers.
Enhances public access to climate information and decision-making.
National Adaptation Strategy: Requires climate risk assessments and adaptation measures in urban planning, water management, and disaster resilience.
The law aligns Portugal’s climate policies with EU regulations and strengthens corporate sustainability reporting requirements.', 'Enacted in December 2021, Portugal’s Climate Framework Law establishes a comprehensive legal framework for climate policy, aligning with the Paris Agreement and the European Green Deal. The law formalizes Portugal’s commitment to carbon neutrality by 2050 and sets legally binding targets for greenhouse gas (GHG) reduction, renewable energy expansion, and climate adaptation measures.

