INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6c0b113e-c9dc-5e17-8725-3ec7a37c043d', 'Portugal Framework climate law', 'Framework climate law no 98/2021', 'The Framework Climate Law no 98/2021 establishes Portugal''s climate policy framework, recognizing a climate emergency and outlining objectives such as transitioning to a sustainable economy, ensuring climate justice, and enhancing resilience. It aims to engage citizens, businesses, and policymakers in climate action and sustainable development.', 'The Framework Climate Law no 98/2021 establishes Portugal''s climate policy framework, recognizing a climate emergency and outlining objectives such as transitioning to a sustainable economy, ensuring climate justice, and enhancing resilience. It aims to engage citizens, businesses, and policymakers in climate action and sustainable development.', 'The Framework Climate Law no 98/2021 establishes Portugal''s climate policy framework, recognizing a climate emergency and outlining objectives such as transitioning to a sustainable economy, ensuring climate justice, and enhancing resilience. It aims to engage citizens, businesses, and policymakers in climate action and sustainable development.', 'Portugal', 'climate', 'in_force', '2021-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_51', ARRAY['sdg13', 'portugal', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f5c99ecd-ca63-5bee-ada4-1bbb8c7e1eaa', 'Portugal National Energy and Climate Plan (PNEC', 'National Energy and Climate Plan (PNEC 2030)', 'The NECP 2030 is Portugal’s primary policy framework for achieving carbon neutrality by 2050. It aligns with EU climate and energy policies and establishes binding targets for reducing greenhouse gas (GHG) emissions, increasing renewable energy capacity, and improving energy efficiency. The plan is structured around the five dimensions of the EU Energy Union:

Decarbonization – Reducing GHG emissions and increasing the share of renewables.
Energy Efficiency – Reducing primary energy consumption.
Energy Security – Ensuring stable and sustainable energy supply.
Internal Energy Market – Enhancing energy interconnectivity and market integration.
Research, Innovation, and Competitiveness – Promoting technological advancements.
Key provisions include:

Emissions Reduction Targets:
45-55% reduction in GHG emissions by 2030 (compared to 2005 levels).
Full decarbonization of the electricity sector by 2040.
Renewable Energy Targets:
47% share of renewables in final energy consumption by 2030.
80% renewable electricity generation by 2030.
Energy Efficiency Goals:
35% reduction in primary energy consumption.
Improved efficiency in buildings, transport, and industrial sectors.
Electricity Interconnections:
Strengthening ties with Spain and France to enhance grid stability.
Sectoral Decarbonization Measures:
Transitioning transport, agriculture, industry, and buildings to low-carbon alternatives.
Promotion of electric mobility and hydrogen production.
The plan also emphasizes public participation, financial incentives, and policy alignment with the EU Green Deal and Paris Agreement.', 'The NECP 2030 is Portugal’s primary policy framework for achieving carbon neutrality by 2050. It aligns with EU climate and energy policies and establishes binding targets for reducing greenhouse gas (GHG) emissions, increasing renewable energy capacity, and improving energy efficiency. The plan is structured around the five dimensions of the EU Energy Union:

