INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3baf8191-66f7-59ad-a96c-e66cbae601fb', 'Portugal Roadmap for Carbon Neutrality 2050 (RNC', 'Roadmap for Carbon Neutrality 2050 (RNC2050)', 'The Roadmap for Carbon Neutrality 2050 (RNC2050) is a strategic plan developed by the Portuguese government to achieve carbon neutrality by 2050. It aims to reduce the country''s greenhouse gas emissions by 85% to 90% below 2005 levels by 2050 through various measures, including increasing the use of renewable energy sources, improving energy efficiency, promoting sustainable mobility, and decarbonizing the industrial and agricultural sectors. The roadmap also includes social and economic considerations, such as job creation and equity, and emphasizes the need for international cooperation to achieve the goals. The plan is updated every five years to track progress and adjust targets.', 'The Roadmap for Carbon Neutrality 2050 (RNC2050) is a strategic plan developed by the Portuguese government to achieve carbon neutrality by 2050. It aims to reduce the country''s greenhouse gas emissions by 85% to 90% below 2005 levels by 2050 through various measures, including increasing the use of renewable energy sources, improving energy efficiency, promoting sustainable mobility, and decarbonizing the industrial and agricultural sectors. The roadmap also includes social and economic considerations, such as job creation and equity, and emphasizes the need for international cooperation to achieve the goals. The plan is updated every five years to track progress and adjust targets.', 'The Roadmap for Carbon Neutrality 2050 (RNC2050) is a strategic plan developed by the Portuguese government to achieve carbon neutrality by 2050. It aims to reduce the country''s greenhouse gas emissions by 85% to 90% below 2005 levels by 2050 through various measures, including increasing the use of renewable energy sources, improving energy efficiency, promoting sustainable mobility, and decarbonizing the industrial and agricultural sectors. The roadmap also includes social and economic considerations, such as job creation and equity, and emphasizes the need for international cooperation to achieve the goals. The plan is updated every five years to track progress and adjust targets.', 'Portugal', 'climate', 'in_force', '2019-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_30', ARRAY['sdg13', 'other sustainability policy', 'portugal', 'sdg7', 'sdg17', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1a6fc85f-6d77-5eef-8590-21e8f3805c59', 'Portugal Social Balance', 'Social Balance, 2018', 'The Balanço Social is a report published annually by the Instituto Nacional da Propriedade Industrial (INPI) of Portugal as part of the Annual Activity Report. The report aims to provide transparency and accountability to the public by disclosing information about the organization''s social, economic, and environmental performance. The report includes data on employee demographics, training and development programs, health and safety initiatives, and social responsibility activities. It also includes information on the organization''s financial performance, such as revenue, expenses, and investments. The Balanço Social is an important tool for stakeholders, including employees, customers, suppliers, and investors, to understand the organization''s impact and contributions to society. It also helps INPI to identify areas for improvement and to establish goals and targets for future performance.', 'The Balanço Social is a report published annually by the Instituto Nacional da Propriedade Industrial (INPI) of Portugal as part of the Annual Activity Report. The report aims to provide transparency and accountability to the public by disclosing information about the organization''s social, economic, and environmental performance. The report includes data on employee demographics, training and development programs, health and safety initiatives, and social responsibility activities. It also includes information on the organization''s financial performance, such as revenue, expenses, and investments. The Balanço Social is an important tool for stakeholders, including employees, customers, suppliers, and investors, to understand the organization''s impact and contributions to society. It also helps INPI to identify areas for improvement and to establish goals and targets for future performance.', 'The Balanço Social is a report published annually by the Instituto Nacional da Propriedade Industrial (INPI) of Portugal as part of the Annual Activity Report. The report aims to provide transparency and accountability to the public by disclosing information about the organization''s social, economic, and environmental performance. The report includes data on employee demographics, training and development programs, health and safety initiatives, and social responsibility activities. It also includes information on the organization''s financial performance, such as revenue, expenses, and investments. The Balanço Social is an important tool for stakeholders, including employees, customers, suppliers, and investors, to understand the organization''s impact and contributions to society. It also helps INPI to identify areas for improvement and to establish goals and targets for future performance.', 'Portugal', 'climate', 'in_force', '2018-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_50', ARRAY['sdg4', 'portugal', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('54b1d155-d612-5767-9296-19c670ea0900', 'Portugal Corporate Governance Code', 'Corporate Governance Code, 2018', 'The Portuguese Institute of Corporate Governance (IPCG) published a new Corporate Governance Code in 2018 that aims to strengthen the practices of good corporate governance in Portugal. The Code is applicable to companies with a primary listing on a regulated market in Portugal, and it provides guidance on key issues such as board composition, internal controls, risk management, and disclosure of information to stakeholders. The Code encourages companies to adopt a long-term and sustainable perspective in their decision-making, and it emphasizes the importance of transparency, accountability, and responsible management. The Code is voluntary, but companies are expected to comply with its recommendations or provide explanations for any deviations.', 'The Portuguese Institute of Corporate Governance (IPCG) published a new Corporate Governance Code in 2018 that aims to strengthen the practices of good corporate governance in Portugal. The Code is applicable to companies with a primary listing on a regulated market in Portugal, and it provides guidance on key issues such as board composition, internal controls, risk management, and disclosure of information to stakeholders. The Code encourages companies to adopt a long-term and sustainable perspective in their decision-making, and it emphasizes the importance of transparency, accountability, and responsible management. The Code is voluntary, but companies are expected to comply with its recommendations or provide explanations for any deviations.', 'The Portuguese Institute of Corporate Governance (IPCG) published a new Corporate Governance Code in 2018 that aims to strengthen the practices of good corporate governance in Portugal. The Code is applicable to companies with a primary listing on a regulated market in Portugal, and it provides guidance on key issues such as board composition, internal controls, risk management, and disclosure of information to stakeholders. The Code encourages companies to adopt a long-term and sustainable perspective in their decision-making, and it emphasizes the importance of transparency, accountability, and responsible management. The Code is voluntary, but companies are expected to comply with its recommendations or provide explanations for any deviations.', 'Portugal', 'climate', 'in_force', '2018-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_9', ARRAY['portugal', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('99724771-4484-5e2f-a19e-8c29e1819bc4', 'Portugal Non-Financial Reporting Disclosure Law (Decree-Law )', 'Non-Financial Reporting Disclosure Law (Decree-Law No. 89/2017)', 'This decree transposes the EU Directive 2014/95/EU into Portuguese law, requiring large companies and public-interest entities (PIEs) to disclose non-financial and diversity information in their annual management reports. The goal is to enhance corporate transparency, stakeholder trust, and sustainability accountability.

Key provisions include:

Entities Covered:
Large companies with over 500 employees.
Parent companies of large corporate groups.
Mandatory Non-Financial Disclosures:
Environmental impact (climate change, pollution, resource use).
Social and labor issues (working conditions, diversity, equal opportunity).
Human rights compliance.
Anti-corruption and bribery policies.
Reporting Format:
Information must be included in the management report or in a separate non-financial statement.
Companies may use EU and international reporting frameworks (e.g., GRI, UN Global Compact, OECD Guidelines).
Verification and Compliance:
Statutory auditors must confirm the presence of non-financial disclosures.
Companies failing to report can face penalties and reputational risks.
The law ensures alignment with EU sustainability policies and reinforces corporate accountability on ESG (Environmental, Social, and Governance) issues.', 'This decree transposes the EU Directive 2014/95/EU into Portuguese law, requiring large companies and public-interest entities (PIEs) to disclose non-financial and diversity information in their annual management reports. The goal is to enhance corporate transparency, stakeholder trust, and sustainability accountability.

