INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('76fc4205-55a5-52c4-ac17-71c5647457e8', 'Portugal Corporate Governance Code', 'Corporate Governance Code, 2016', 'The Corporate Governance Code of 2016 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, risk management, audit committees, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business.', 'The Corporate Governance Code of 2016 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, risk management, audit committees, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business.', 'The Corporate Governance Code of 2016 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, risk management, audit committees, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business.', 'Portugal', 'climate', 'in_force', '2016-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_18', ARRAY['portugal', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('411012ac-4bae-5265-ab1c-22156a005426', 'Portugal Transposition of EU NFR Directive: Amendment to the', 'Transposition of EU NFR Directive: Amendment to the Accounting Act', 'The Transposition of the EU Non-Financial Reporting Directive (2014/95/EU) into Portuguese law led to an amendment to the Accounting Act in 2016. The amendment requires large public-interest entities (PIEs) to disclose non-financial information, such as information on environmental, social, and employee-related matters, respect for human rights, and anti-corruption and bribery issues, in their management reports. This obligation applied to companies with more than 500 employees or with a turnover of over €40 million. The objective of the transposition was to increase transparency and accountability of large companies regarding their non-financial impacts and risks, thereby contributing to sustainable development.', 'The Transposition of the EU Non-Financial Reporting Directive (2014/95/EU) into Portuguese law led to an amendment to the Accounting Act in 2016. The amendment requires large public-interest entities (PIEs) to disclose non-financial information, such as information on environmental, social, and employee-related matters, respect for human rights, and anti-corruption and bribery issues, in their management reports. This obligation applied to companies with more than 500 employees or with a turnover of over €40 million. The objective of the transposition was to increase transparency and accountability of large companies regarding their non-financial impacts and risks, thereby contributing to sustainable development.', 'The Transposition of the EU Non-Financial Reporting Directive (2014/95/EU) into Portuguese law led to an amendment to the Accounting Act in 2016. The amendment requires large public-interest entities (PIEs) to disclose non-financial information, such as information on environmental, social, and employee-related matters, respect for human rights, and anti-corruption and bribery issues, in their management reports. This obligation applied to companies with more than 500 employees or with a turnover of over €40 million. The objective of the transposition was to increase transparency and accountability of large companies regarding their non-financial impacts and risks, thereby contributing to sustainable development.', 'Portugal', 'climate', 'in_force', '2016-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_32', ARRAY['portugal', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0522ad65-6221-59eb-95d5-08b64309a9f9', 'Portugal Ordinance', 'Ordinance No. 84/2015', 'A regulation that establishes guidelines for the implementation of social responsibility practices in Portugal. The regulation aims to promote the integration of social responsibility into the activities of businesses and organizations, with the aim of contributing to sustainable development and social cohesion. The regulation sets out the requirements for the implementation of a social responsibility management system, including the development of a social responsibility policy, the identification of stakeholders, and the implementation of social responsibility initiatives. The regulation is applicable to all businesses and organizations operating in Portugal, and provides a framework for the development of socially responsible practices.', 'A regulation that establishes guidelines for the implementation of social responsibility practices in Portugal. The regulation aims to promote the integration of social responsibility into the activities of businesses and organizations, with the aim of contributing to sustainable development and social cohesion. The regulation sets out the requirements for the implementation of a social responsibility management system, including the development of a social responsibility policy, the identification of stakeholders, and the implementation of social responsibility initiatives. The regulation is applicable to all businesses and organizations operating in Portugal, and provides a framework for the development of socially responsible practices.', 'A regulation that establishes guidelines for the implementation of social responsibility practices in Portugal. The regulation aims to promote the integration of social responsibility into the activities of businesses and organizations, with the aim of contributing to sustainable development and social cohesion. The regulation sets out the requirements for the implementation of a social responsibility management system, including the development of a social responsibility policy, the identification of stakeholders, and the implementation of social responsibility initiatives. The regulation is applicable to all businesses and organizations operating in Portugal, and provides a framework for the development of socially responsible practices.', 'Portugal', 'climate', 'in_force', '2015-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_7', ARRAY['sdg8', 'other sustainability policy', 'portugal', 'regulations', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fd9a3dc7-b19e-5dde-8cdc-b04616992baa', 'Portugal Resolution of the Council of Ministers', 'Resolution of the Council of Ministers No. 18/2014', 'Resolução do Conselho de Ministros n.o 18/2014 is a resolution that approves the National Plan for CSR (Corporate Social Responsibility) for the period 2014-2020. The plan aims to promote and encourage CSR practices in Portuguese companies, and it is aligned with the EU strategy for CSR. The plan defines CSR as a concept that covers the social, environmental, and economic dimensions of sustainability, and it sets out a series of actions to be implemented by the government, companies, and other stakeholders to promote CSR. The plan also establishes a monitoring system to assess the progress of its implementation and impact on society and the environment.', 'Resolução do Conselho de Ministros n.o 18/2014 is a resolution that approves the National Plan for CSR (Corporate Social Responsibility) for the period 2014-2020. The plan aims to promote and encourage CSR practices in Portuguese companies, and it is aligned with the EU strategy for CSR. The plan defines CSR as a concept that covers the social, environmental, and economic dimensions of sustainability, and it sets out a series of actions to be implemented by the government, companies, and other stakeholders to promote CSR. The plan also establishes a monitoring system to assess the progress of its implementation and impact on society and the environment.', 'Resolução do Conselho de Ministros n.o 18/2014 is a resolution that approves the National Plan for CSR (Corporate Social Responsibility) for the period 2014-2020. The plan aims to promote and encourage CSR practices in Portuguese companies, and it is aligned with the EU strategy for CSR. The plan defines CSR as a concept that covers the social, environmental, and economic dimensions of sustainability, and it sets out a series of actions to be implemented by the government, companies, and other stakeholders to promote CSR. The plan also establishes a monitoring system to assess the progress of its implementation and impact on society and the environment.', 'Portugal', 'climate', 'in_force', '2014-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_8', ARRAY['sdg13', 'other sustainability policy', 'portugal', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1960553e-c070-5b4f-a834-4a402f8317aa', 'Portugal CMVM Corporate Governance Code 2013 (Recommendations)', 'CMVM Corporate Governance Code 2013 (Recommendations)', 'The Corporate Governance Code of 2013 (Recommendations) is an updated set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, shareholder rights, and transparency. The code is based on the principles of the 2010 code but includes some additional recommendations, such as those related to risk management and internal controls. The 2013 code is not mandatory, but companies are encouraged to adopt its recommendations to enhance transparency, accountability, and shareholder value.', 'The Corporate Governance Code of 2013 (Recommendations) is an updated set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, shareholder rights, and transparency. The code is based on the principles of the 2010 code but includes some additional recommendations, such as those related to risk management and internal controls. The 2013 code is not mandatory, but companies are encouraged to adopt its recommendations to enhance transparency, accountability, and shareholder value.', 'The Corporate Governance Code of 2013 (Recommendations) is an updated set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, shareholder rights, and transparency. The code is based on the principles of the 2010 code but includes some additional recommendations, such as those related to risk management and internal controls. The 2013 code is not mandatory, but companies are encouraged to adopt its recommendations to enhance transparency, accountability, and shareholder value.', 'Portugal', 'climate', 'in_force', '2013-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_15', ARRAY['guidance_frameworks', 'portugal', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fd9c3704-110e-565c-a73f-016ec56f26ca', 'Portugal CMVM Regulation Corporate Governance', 'CMVM Regulation No. 4/2013 Corporate Governance', 'CMVM Regulation No 4/2013 is a regulation issued by the Portuguese Securities Market Commission (CMVM) that provides guidelines and rules for companies listed on the Portuguese stock exchange to ensure they comply with good corporate governance practices. The regulation covers a wide range of topics, including board of directors'' duties, the role of shareholders, the audit process, and transparency and disclosure requirements. It aims to strengthen the integrity and efficiency of the capital markets in Portugal, to protect investors'' rights and to promote the long-term sustainable development of companies.', 'CMVM Regulation No 4/2013 is a regulation issued by the Portuguese Securities Market Commission (CMVM) that provides guidelines and rules for companies listed on the Portuguese stock exchange to ensure they comply with good corporate governance practices. The regulation covers a wide range of topics, including board of directors'' duties, the role of shareholders, the audit process, and transparency and disclosure requirements. It aims to strengthen the integrity and efficiency of the capital markets in Portugal, to protect investors'' rights and to promote the long-term sustainable development of companies.', 'CMVM Regulation No 4/2013 is a regulation issued by the Portuguese Securities Market Commission (CMVM) that provides guidelines and rules for companies listed on the Portuguese stock exchange to ensure they comply with good corporate governance practices. The regulation covers a wide range of topics, including board of directors'' duties, the role of shareholders, the audit process, and transparency and disclosure requirements. It aims to strengthen the integrity and efficiency of the capital markets in Portugal, to protect investors'' rights and to promote the long-term sustainable development of companies.', 'Portugal', 'climate', 'in_force', '2013-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_29', ARRAY['portugal', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('32fdc5f1-3b7b-5bf0-93fe-03a46385d92c', 'Portugal Corporate Governance Code', 'Corporate Governance Code, 2012', 'The Corporate Governance Code of 2012 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business. The code has been updated several times since its introduction in 2012 to reflect changes in best practices and market conditions.', 'The Corporate Governance Code of 2012 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business. The code has been updated several times since its introduction in 2012 to reflect changes in best practices and market conditions.', 'The Corporate Governance Code of 2012 is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to promote good corporate governance practices among companies listed on the Portuguese stock exchange. The code covers topics such as board composition and functioning, remuneration, audit committees, risk management, shareholder rights, and disclosure of information. The code is based on internationally recognized principles and aims to enhance transparency, accountability, and shareholder value. While the code is not mandatory, companies are encouraged to adopt its recommendations to promote investor confidence and ensure the long-term success of their business. The code has been updated several times since its introduction in 2012 to reflect changes in best practices and market conditions.', 'Portugal', 'climate', 'in_force', '2012-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_19', ARRAY['portugal', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46292851-d32c-5883-a15b-5ee6f958a145', 'Portugal CMVM Corporate Governance Code 2010 (Recommendations)', 'CMVM Corporate Governance Code 2010 (Recommendations)', 'The Corporate Governance Code of 2010 (Recommendations) is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to improve corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, shareholder rights, and transparency. Unlike the 2007 code, the 2010 version is not prescriptive and companies are not required to comply with the recommendations. However, companies are encouraged to adopt the best practices outlined in the code to enhance transparency, accountability, and shareholder value, and to promote investor confidence in the Portuguese market.', 'The Corporate Governance Code of 2010 (Recommendations) is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to improve corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, shareholder rights, and transparency. Unlike the 2007 code, the 2010 version is not prescriptive and companies are not required to comply with the recommendations. However, companies are encouraged to adopt the best practices outlined in the code to enhance transparency, accountability, and shareholder value, and to promote investor confidence in the Portuguese market.', 'The Corporate Governance Code of 2010 (Recommendations) is a set of recommendations issued by the Portuguese Securities Market Commission (CMVM) to improve corporate governance practices among companies listed on the Portuguese stock exchange. The recommendations cover topics such as board composition and functioning, remuneration, shareholder rights, and transparency. Unlike the 2007 code, the 2010 version is not prescriptive and companies are not required to comply with the recommendations. However, companies are encouraged to adopt the best practices outlined in the code to enhance transparency, accountability, and shareholder value, and to promote investor confidence in the Portuguese market.', 'Portugal', 'climate', 'in_force', '2010-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_14', ARRAY['guidance_frameworks', 'portugal', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e3db36e4-092f-5908-9c35-d6f0e5aab263', 'Portugal Corporate Governance Code and Legal Framework Consolidation', 'Corporate Governance Code and Legal Framework Consolidation, 2010', 'The Corporate Governance Code and Legal Framework Consolidation of 2010 by the Comissão do Mercado de Valores Mobiliários (CMVM) aimed to consolidate the existing legal framework related to corporate governance practices in Portugal. The document provides a comprehensive overview of the various laws, regulations, and recommendations that companies must adhere to when implementing good corporate governance practices. It also includes a summary of the CMVM''s recommendations on corporate governance, with a focus on board structure, director responsibilities, and the role of shareholders. Overall, the consolidation serves as a valuable resource for companies seeking to improve their corporate governance practices in Portugal.', 'The Corporate Governance Code and Legal Framework Consolidation of 2010 by the Comissão do Mercado de Valores Mobiliários (CMVM) aimed to consolidate the existing legal framework related to corporate governance practices in Portugal. The document provides a comprehensive overview of the various laws, regulations, and recommendations that companies must adhere to when implementing good corporate governance practices. It also includes a summary of the CMVM''s recommendations on corporate governance, with a focus on board structure, director responsibilities, and the role of shareholders. Overall, the consolidation serves as a valuable resource for companies seeking to improve their corporate governance practices in Portugal.', 'The Corporate Governance Code and Legal Framework Consolidation of 2010 by the Comissão do Mercado de Valores Mobiliários (CMVM) aimed to consolidate the existing legal framework related to corporate governance practices in Portugal. The document provides a comprehensive overview of the various laws, regulations, and recommendations that companies must adhere to when implementing good corporate governance practices. It also includes a summary of the CMVM''s recommendations on corporate governance, with a focus on board structure, director responsibilities, and the role of shareholders. Overall, the consolidation serves as a valuable resource for companies seeking to improve their corporate governance practices in Portugal.', 'Portugal', 'climate', 'in_force', '2010-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_25', ARRAY['voluntary_frameworks', 'portugal', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('efc4695e-f0ad-5ed0-b028-d78cc66d691c', 'Portugal Law n.o', 'Law n.o 7/2009', 'Law no. 7/2009 was passed in Portugal to revise the Labor Code in order to improve the regulation of working conditions and relations between employers and employees. The main changes included increasing the minimum wage, establishing a minimum period of notice for termination of employment contracts, extending the scope of collective bargaining agreements, and improving the rights of part-time and temporary workers. The law also aimed to enhance protection for workers in cases of dismissal, redundancy, and collective dismissal, and introduced new measures to ensure equal treatment of employees regardless of their gender, age, or nationality.', 'Law no. 7/2009 was passed in Portugal to revise the Labor Code in order to improve the regulation of working conditions and relations between employers and employees. The main changes included increasing the minimum wage, establishing a minimum period of notice for termination of employment contracts, extending the scope of collective bargaining agreements, and improving the rights of part-time and temporary workers. The law also aimed to enhance protection for workers in cases of dismissal, redundancy, and collective dismissal, and introduced new measures to ensure equal treatment of employees regardless of their gender, age, or nationality.', 'Law no. 7/2009 was passed in Portugal to revise the Labor Code in order to improve the regulation of working conditions and relations between employers and employees. The main changes included increasing the minimum wage, establishing a minimum period of notice for termination of employment contracts, extending the scope of collective bargaining agreements, and improving the rights of part-time and temporary workers. The law also aimed to enhance protection for workers in cases of dismissal, redundancy, and collective dismissal, and introduced new measures to ensure equal treatment of employees regardless of their gender, age, or nationality.', 'Portugal', 'climate', 'in_force', '2009-01-01'::date, 'Portugal', 'https://www.carrotsandsticks.org/policies/146_12', ARRAY['sdg8', 'portugal', 'regulations', 'mandatory', 'sdg5', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
